from torch.utils.data import Dataset

class FederDataset(Dataset):
    def __init__(self, s, F):
        self.s = s
        self.F = F

    def __len__(self):
        return len(self.s)

    def __getitem__(self, idx):
        return self.s[idx], self.F[idx]

